import{_t as e,it as t,n,rt as r}from"./chunks/framework.DTuxy4X8.js";var i=JSON.parse(`{"title":"Standards Scope","description":"","frontmatter":{"packageVersion":"0.9.0"},"headers":[],"relativePath":"reference/standards.md","filePath":"site/versions/v0.9.0/reference/standards.md","lastUpdated":0}`),a={name:`reference/standards.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="standards-scope" tabindex="-1">Standards Scope <a class="header-anchor" href="#standards-scope" aria-label="Permalink to “Standards Scope”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>RFC 5280 path validation</td><td>complete</td><td>Full NIST PKITS suite passes (224 procedures, 249 runs; DSA chains expected-fail per the WebCrypto algorithm boundary); revocation is a separate API by design</td></tr><tr><td>RFC 6960 OCSP</td><td>complete</td><td>Full validation surface: parsing, signatures, responder authorization, revocation policy, nonce, freshness, chain orchestration; HTTP transport caller-provided by design</td></tr><tr><td>RFC 6125 service identity</td><td>complete</td><td>Every identity type: DNS-ID, IP-ID, URI-ID, SRV-ID, wildcard, IDNA, opt-in CN-compat</td></tr><tr><td>RFC 9618 policy validation</td><td>complete</td><td>Full PKITS policy sections (4.8–4.12, every documented subtest variation) pass</td></tr></tbody></table><h2 id="what-ships" tabindex="-1">What ships <a class="header-anchor" href="#what-ships" aria-label="Permalink to “What ships”">​</a></h2><h3 id="rfc-5280-path-validation" tabindex="-1">RFC 5280 path validation <a class="header-anchor" href="#rfc-5280-path-validation" aria-label="Permalink to “RFC 5280 path validation”">​</a></h3><ul><li>DER parsing strict enough to reject malformed certificates</li><li>Issuer/subject chaining across candidate paths</li><li>Signature verification using the evolving working public key</li><li>Validity time checks (<code>notBefore</code> / <code>notAfter</code>)</li><li><code>basicConstraints</code> enforcement for CA certificates</li><li><code>pathLenConstraint</code> enforcement</li><li><code>keyUsage</code> enforcement (<code>keyCertSign</code> for CAs)</li><li>Self-issued vs non-self-issued processing</li><li>Name constraints: enforced for DNS, URI, email, IP, and directoryName; fail-closed for otherName / x400Address / ediPartyName / registeredID when a critical constraint meets a SAN of that form (RFC 5280 §4.2.1.10)</li><li>Critical extension rejection for unrecognized OIDs</li></ul><h3 id="rfc-6960-ocsp" tabindex="-1">RFC 6960 OCSP <a class="header-anchor" href="#rfc-6960-ocsp" aria-label="Permalink to “RFC 6960 OCSP”">​</a></h3><ul><li>Request creation with CertID (issuer hash + serial)</li><li>Response parsing with status, certs, timestamps</li><li>Signature verification</li><li>Responder authorization (CA-signed, delegated with <code>ocspSigning</code> EKU, locally trusted responders per RFC 6960 §4.2.2.2 criterion 1)</li><li>Delegated responder revocation policy: <code>id-pkix-ocsp-nocheck</code> (<code>hasOcspNoCheckExtension()</code>), <code>honor-nocheck</code> / <code>require-evidence</code> / <code>skip</code> knobs with CRL evidence</li><li>Historical-time responder chain validation (<code>at</code> flows through delegated chain checks)</li><li>Nonce matching</li><li>Freshness checks</li><li>Chain-level orchestration: <code>checkChainRevocation()</code> / <code>verifyCertificateChain({ revocation })</code> consume caller-supplied OCSP responses alongside CRLs</li></ul><h3 id="crl-processing" tabindex="-1">CRL processing <a class="header-anchor" href="#crl-processing" aria-label="Permalink to “CRL processing”">​</a></h3><ul><li>Delta CRL merge</li><li>Indirect issuer handling</li><li>Scope matching</li><li>Basic CRL parsing and revocation checks</li></ul><div class="tip custom-block"><p class="custom-block-title">Hard-fail default</p><p>Chain-level revocation checking runs only when evidence is supplied, and then defaults to <code>mode: &#39;hard-fail&#39;</code> — indeterminate status denies. Set <code>mode: &#39;soft-fail&#39;</code> explicitly to allow indeterminate results. See the <a href="/v0.9.0/guide/revocation">revocation guide</a>.</p></div><h3 id="rfc-6125-service-identity" tabindex="-1">RFC 6125 service identity <a class="header-anchor" href="#rfc-6125-service-identity" aria-label="Permalink to “RFC 6125 service identity”">​</a></h3><ul><li>DNS-ID with single-level wildcard matching</li><li>IP-ID with IPv6 normalization</li><li>URI-ID scheme + host matching</li><li>SRV-ID via otherName SAN</li><li>IDNA-aware comparison</li><li>Opt-in CN compatibility (disabled by default)</li></ul><h3 id="rfc-9618-policy-validation" tabindex="-1">RFC 9618 policy validation <a class="header-anchor" href="#rfc-9618-policy-validation" aria-label="Permalink to “RFC 9618 policy validation”">​</a></h3><ul><li>Policy state tracking across candidate paths</li><li>Explicit policy enforcement</li><li>Initial policy set validation</li></ul><h2 id="what-doesn-t-ship" tabindex="-1">What doesn&#39;t ship <a class="header-anchor" href="#what-doesn-t-ship" aria-label="Permalink to “What doesn&#39;t ship”">​</a></h2><ul><li>Full CRL distribution point processing</li><li>OCSP/CRL HTTP fetching (evidence is caller-provided by design)</li><li>Semantic matching for otherName / x400Address / ediPartyName / registeredID name constraints (they fail closed instead when a critical constraint meets a name of that form)</li></ul><p>For the authoritative scope boundary, see <a href="https://github.com/kjanat/micro509/blob/master/docs/PKIX-SCOPE.md" target="_blank" rel="noreferrer"><code>PKIX-SCOPE.md</code></a>.</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};